#!/usr/bin/env python3
"""
residual_gates_numpy.py
NumPy drop-in twin of ResidualGates.lean + InnerSolve.FormalMod.

Teaching card
1. Grant is stored only with mask == 0.
2. Claimed ≤ interior, coordinatewise. Shape mismatch is not enclosed.
3. gateA compares integer residualSq to tolSq; tolSq must be strictly positive.
4. crewBound is undefined at solo == 0 or lambda == 0 or size == 0.
5. This file is a numerical twin. It is not a Lean kernel receipt.
   Physical grant REFUSED. MAGPIE stays 19/658,750 pending.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Iterable, Optional, Sequence, Tuple, Union

import numpy as np

ArrayLike = Union[np.ndarray, Sequence[int], Sequence[Sequence[int]]]

# ---------------------------------------------------------------------------
# ResidualGates — Lean kernel twin
# ---------------------------------------------------------------------------


class GateStatus(str, Enum):
    GRANT = "grant"
    REFUSE = "refuse"


@dataclass(frozen=True)
class GateDecision:
    status: GateStatus
    mask: int
    failed_indices: Tuple[int, ...] = field(default_factory=tuple)

    def granted(self) -> bool:
        return self.status is GateStatus.GRANT and self.mask == 0


def _as_i64_vec(v: ArrayLike, name: str) -> np.ndarray:
    a = np.asarray(v, dtype=np.int64)
    if a.ndim != 1:
        raise ValueError(f"{name} must be a 1-D integer vector, got shape {a.shape}")
    return a


def _as_i64_mat(L: ArrayLike, name: str) -> np.ndarray:
    a = np.asarray(L, dtype=np.int64)
    if a.ndim != 2:
        raise ValueError(f"{name} must be a 2-D integer matrix, got shape {a.shape}")
    return a


def enclosed(interior: ArrayLike, claimed: ArrayLike) -> bool:
    """Claimed ≤ interior on every coordinate. Shape mismatch is not enclosed."""
    i = np.asarray(interior, dtype=np.int64)
    c = np.asarray(claimed, dtype=np.int64)
    if i.shape != c.shape:
        return False
    return bool(np.all(c <= i))


def breaches(interior: ArrayLike, claimed: ArrayLike) -> np.ndarray:
    """Indices where claimed > interior. Empty on shape mismatch."""
    i = np.asarray(interior, dtype=np.int64)
    c = np.asarray(claimed, dtype=np.int64)
    if i.shape != c.shape:
        return np.array([], dtype=np.int64)
    return np.flatnonzero(c > i).astype(np.int64)


def mask_of(failed: Iterable[int]) -> int:
    """OR of 1 << idx. mask_of([]) == 0. mask_of([1, 3]) == 10."""
    acc = 0
    for idx in failed:
        if idx < 0:
            raise ValueError("failed index must be ≥ 0")
        acc |= 1 << int(idx)
    return int(acc)


def granted(d: GateDecision) -> bool:
    return d.granted()


def gate_b(interior: ArrayLike, claimed: ArrayLike) -> GateDecision:
    """Coordinatewise claimed ≤ interior. Grant implies mask == 0."""
    if enclosed(interior, claimed):
        return GateDecision(GateStatus.GRANT, 0, ())
    failed = tuple(int(x) for x in breaches(interior, claimed).tolist())
    m = mask_of(failed)
    return GateDecision(GateStatus.REFUSE, 1 if m == 0 else m, failed)


def mat_vec(L: ArrayLike, x: ArrayLike) -> np.ndarray:
    """Integer matrix-vector product. Length mismatch refuses (no silent zip)."""
    A = _as_i64_mat(L, "L")
    v = _as_i64_vec(x, "x")
    if A.shape[1] != v.shape[0]:
        raise ValueError(f"mat_vec shape mismatch: L {A.shape} vs x {v.shape}")
    return A @ v


def residual_sq(L: ArrayLike, b: ArrayLike, x: ArrayLike) -> int:
    """||b − Lx||² on int64. Shape mismatch raises."""
    A = _as_i64_mat(L, "L")
    rhs = _as_i64_vec(b, "b")
    v = _as_i64_vec(x, "x")
    if A.shape[0] != rhs.shape[0] or A.shape[1] != v.shape[0]:
        raise ValueError(
            f"residual_sq shape mismatch: L {A.shape} b {rhs.shape} x {v.shape}"
        )
    r = rhs - (A @ v)
    return int(np.dot(r, r))


def gate_a(L: ArrayLike, b: ArrayLike, x: ArrayLike, tol_sq: int) -> GateDecision:
    """Grant iff 0 < tol_sq and residual_sq ≤ tol_sq."""
    try:
        rsq = residual_sq(L, b, x)
    except ValueError:
        return GateDecision(GateStatus.REFUSE, 1, (0,))
    if 0 < int(tol_sq) and rsq <= int(tol_sq):
        return GateDecision(GateStatus.GRANT, 0, ())
    return GateDecision(GateStatus.REFUSE, 1, (0,))


def crew_bound(solo: int, lam: int, size: int) -> Optional[int]:
    """solo * λ * size, or None when any factor is not strictly admissible."""
    if solo > 0 and lam >= 1 and size >= 1:
        return int(solo) * int(lam) * int(size)
    return None


def crew_admissible(claimed: int, solo: int, lam: int, size: int) -> bool:
    bound = crew_bound(solo, lam, size)
    if bound is None:
        return False
    return int(claimed) <= bound


def admit(
    L: ArrayLike,
    b: ArrayLike,
    x: ArrayLike,
    tol_sq: int,
    interior: ArrayLike,
    claimed: ArrayLike,
) -> GateDecision:
    """Both gates must grant. Combined mask is bitwise OR, never left at 0 on refuse."""
    a = gate_a(L, b, x, tol_sq)
    bd = gate_b(interior, claimed)
    if a.granted() and bd.granted():
        return GateDecision(GateStatus.GRANT, 0, ())
    m = a.mask | bd.mask
    failed = a.failed_indices + bd.failed_indices
    return GateDecision(GateStatus.REFUSE, 1 if m == 0 else m, failed)


# Lean sample vectors (Python-parity suite)
SAMPLE_INTERIOR = np.array([100, 50, 25, 10], dtype=np.int64)
SAMPLE_VALID = np.array([98, 49, 25, 9], dtype=np.int64)
SAMPLE_INVALID = np.array([98, 51, 25, 11], dtype=np.int64)
SAMPLE_L = np.array([[4, 1, 0], [1, 3, 1], [0, 1, 2]], dtype=np.int64)
SAMPLE_B = np.array([5, 5, 3], dtype=np.int64)
SAMPLE_X_CORRUPT = np.array([2, 1, 1], dtype=np.int64)


# ---------------------------------------------------------------------------
# InnerSolve.FormalMod — Word128 checked arithmetic + two-gate job
# ---------------------------------------------------------------------------

BIT128 = 1 << 128


@dataclass(frozen=True)
class Word128:
    raw: int

    def __post_init__(self) -> None:
        if not (0 <= int(self.raw) < BIT128):
            raise OverflowError("Word128 raw must satisfy 0 ≤ raw < 2^128")

    @classmethod
    def zero(cls) -> "Word128":
        return cls(0)


def checked_add(a: Word128, b: Word128) -> Optional[Word128]:
    s = int(a.raw) + int(b.raw)
    if s < BIT128:
        return Word128(s)
    return None


@dataclass(frozen=True)
class ResourceVec:
    C: Word128
    M: Word128
    P: Word128
    Q: Word128

    @classmethod
    def from_ints(cls, C: int, M: int, P: int, Q: int) -> "ResourceVec":
        return cls(Word128(C), Word128(M), Word128(P), Word128(Q))

    def as_array(self) -> np.ndarray:
        return np.array([self.C.raw, self.M.raw, self.P.raw, self.Q.raw], dtype=object)


InteriorVec = ResourceVec


def component_admit(claimed: Word128, interior: Word128) -> bool:
    return int(claimed.raw) <= int(interior.raw)


def vector_admit(c: ResourceVec, I: InteriorVec) -> bool:
    return bool(
        enclosed(
            [I.C.raw, I.M.raw, I.P.raw, I.Q.raw],
            [c.C.raw, c.M.raw, c.P.raw, c.Q.raw],
        )
    )


def may_dispatch(c: ResourceVec, I: InteriorVec) -> bool:
    return vector_admit(c, I)


def accrue(base: Word128, inc: Word128) -> Optional[Word128]:
    return checked_add(base, inc)


def accrue_vec(base: ResourceVec, inc: ResourceVec) -> Optional[ResourceVec]:
    C = accrue(base.C, inc.C)
    M = accrue(base.M, inc.M)
    P = accrue(base.P, inc.P)
    Q = accrue(base.Q, inc.Q)
    if None in (C, M, P, Q):
        return None
    return ResourceVec(C, M, P, Q)  # type: ignore[arg-type]


@dataclass(frozen=True)
class LinSys:
    b_in_range: bool


def residual_norm_sq(sys: LinSys, on_range: bool) -> int:
    return 0 if on_range else 1


def strict_closure(sys: LinSys) -> bool:
    return residual_norm_sq(sys, sys.b_in_range) == 0


def projected_admit(sys: LinSys) -> bool:
    return sys.b_in_range is True


@dataclass(frozen=True)
class InnerSolveJob:
    claim: ResourceVec
    room: InteriorVec
    sys: LinSys
    claim_zero_residual: bool


def job_admit(j: InnerSolveJob) -> bool:
    if not may_dispatch(j.claim, j.room):
        return False
    if j.claim_zero_residual and not j.sys.b_in_range:
        return False
    return True


# Aliases matching Lean camelCase for drop-in callers
gateB = gate_b
gateA = gate_a
maskOf = mask_of
matVec = mat_vec
residualSq = residual_sq
crewBound = crew_bound
crewAdmissible = crew_admissible
mayDispatch = may_dispatch
checkedAdd = checked_add
accrueVec = accrue_vec
residualNormSq = residual_norm_sq
strictClosure = strict_closure
projectedAdmit = projected_admit
jobAdmit = job_admit


def self_test() -> None:
    """Parity with ResidualGates.lean native_decide + InnerSolve theorems."""
    assert mask_of([]) == 0
    assert mask_of([1, 3]) == 10
    assert enclosed([], []) is True
    assert enclosed(SAMPLE_INTERIOR, SAMPLE_INTERIOR) is True
    assert enclosed(SAMPLE_INTERIOR, SAMPLE_VALID) is True
    assert enclosed(SAMPLE_INTERIOR, SAMPLE_INVALID) is False
    assert enclosed([1, 2], [1]) is False

    ok = gate_b(SAMPLE_INTERIOR, SAMPLE_VALID)
    assert granted(ok) is True
    assert ok.status is GateStatus.GRANT and ok.mask == 0

    bad = gate_b(SAMPLE_INTERIOR, SAMPLE_INVALID)
    assert bad.status is GateStatus.REFUSE
    assert bad.mask == 10
    assert bad.failed_indices == (1, 3)
    assert granted(bad) is False

    self_g = gate_b(SAMPLE_INTERIOR, SAMPLE_INTERIOR)
    assert self_g.status is GateStatus.GRANT and self_g.mask == 0

    assert crew_bound(4, 0, 3) is None
    assert crew_bound(0, 2, 3) is None
    assert crew_bound(4, 2, 3) == 24
    assert crew_admissible(24, 4, 2, 3) is True
    assert crew_admissible(25, 4, 2, 3) is False

    rsq = residual_sq(SAMPLE_L, SAMPLE_B, SAMPLE_X_CORRUPT)
    assert rsq == 17  # Lx=[9,6,3], r=[-4,-1,0]
    assert gate_a(SAMPLE_L, SAMPLE_B, SAMPLE_X_CORRUPT, 0).status is GateStatus.REFUSE

    # exact integer solve of SAMPLE_L x = SAMPLE_B is not required;
    # x = [1, 1, 1] gives Lx = [5, 5, 3] = b, residual 0.
    exact = np.array([1, 1, 1], dtype=np.int64)
    assert residual_sq(SAMPLE_L, SAMPLE_B, exact) == 0
    assert gate_a(SAMPLE_L, SAMPLE_B, exact, 1).status is GateStatus.GRANT

    both = admit(SAMPLE_L, SAMPLE_B, exact, 1, SAMPLE_INTERIOR, SAMPLE_VALID)
    assert granted(both) is True
    refused = admit(SAMPLE_L, SAMPLE_B, SAMPLE_X_CORRUPT, 0, SAMPLE_INTERIOR, SAMPLE_INVALID)
    assert granted(refused) is False
    assert refused.mask != 0

    # Word128
    assert checked_add(Word128(1), Word128(1)).raw == 2  # type: ignore[union-attr]
    assert checked_add(Word128(BIT128 - 1), Word128(1)) is None
    room = ResourceVec.from_ints(10, 10, 10, 10)
    claim_ok = ResourceVec.from_ints(9, 9, 9, 9)
    claim_bad = ResourceVec.from_ints(11, 0, 0, 0)
    assert may_dispatch(claim_ok, room) is True
    assert may_dispatch(claim_bad, room) is False
    assert accrue_vec(claim_ok, ResourceVec.from_ints(1, 1, 1, 1)) is not None
    overflow = accrue_vec(
        ResourceVec.from_ints(BIT128 - 1, 0, 0, 0),
        ResourceVec.from_ints(1, 0, 0, 0),
    )
    assert overflow is None

    on = LinSys(True)
    off = LinSys(False)
    assert strict_closure(on) is True
    assert strict_closure(off) is False
    assert residual_norm_sq(off, False) == 1

    job_ok = InnerSolveJob(claim_ok, room, on, True)
    job_lie = InnerSolveJob(claim_ok, room, off, True)
    job_over = InnerSolveJob(claim_bad, room, on, False)
    assert job_admit(job_ok) is True
    assert job_admit(job_lie) is False
    assert job_admit(job_over) is False


if __name__ == "__main__":
    self_test()
    print("residual_gates_numpy: all parity asserts passed")
    print("physical_grant=REFUSED")
    print("MAGPIE=19/658,750 pending")

"""Members Gate. Labeled-figure admission.

A figure is admitted only under its own label.
Equal counts do not merge figures.
Headroom does not cross labels.
A missing label is a refusal.
A later record is not a first occurrence.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Mapping, Optional, Sequence


@dataclass(frozen=True)
class Figure:
    label: str
    count: int

    def __post_init__(self) -> None:
        if not isinstance(self.label, str) or self.label == "":
            raise ValueError("a figure needs its own label")
        if not isinstance(self.count, int):
            raise ValueError("count must be an integer")


@dataclass(frozen=True)
class Record:
    record_id: str
    figures: tuple
    closed: bool = True

    def by_label(self) -> dict:
        found = {}
        for figure in self.figures:
            if figure.label in found:
                raise ValueError(f"duplicate label in record {self.record_id}: {figure.label}")
            found[figure.label] = figure
        return found


@dataclass(frozen=True)
class LabelResult:
    label: str
    claimed: object
    interior: object
    headroom: object
    admitted: bool
    reason: str


@dataclass(frozen=True)
class Decision:
    decision_id: str
    claimed_id: str
    interior_id: str
    admitted: bool
    results: tuple
    created_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

    @property
    def failing_labels(self) -> tuple:
        return tuple(row.label for row in self.results if not row.admitted)


def record_from_counts(record_id: str, labels, counts) -> Record:
    if len(labels) != len(counts):
        raise ValueError("labels and counts must have the same length")
    figures = tuple(Figure(label, count) for label, count in zip(labels, counts))
    return Record(record_id, figures, closed=True)


def compare(claimed: Record, interior: Record, decision_id: str) -> Decision:
    if not claimed.closed or not interior.closed:
        raise ValueError("comparison requires closed records")
    claimed_map = claimed.by_label()
    interior_map = interior.by_label()
    results = []
    for label, figure in claimed_map.items():
        other = interior_map.get(label)
        if other is None:
            results.append(LabelResult(label, figure.count, None, None, False, "missing interior label"))
            continue
        headroom = other.count - figure.count
        if headroom < 0:
            results.append(LabelResult(label, figure.count, other.count, headroom, False, "deficit"))
        else:
            results.append(LabelResult(label, figure.count, other.count, headroom, True, "fits"))
    admitted = all(row.admitted for row in results) and len(results) > 0
    return Decision(decision_id, claimed.record_id, interior.record_id, admitted, tuple(results))


def worked_case() -> Decision:
    labels = ("A", "B", "C", "D")
    claimed = record_from_counts("request-0031", labels, (1, 0, 1, 1))
    interior = record_from_counts("interior-0031", labels, (1, 1, 0, 1))
    return compare(claimed, interior, "decision-0031")

# house_elf_desk.py — existing House Elf / House Elf II desktop lane only.
# Not a new product. Not the Drive cabinet skill. Not PULSE, Kiln, Hermes, or residual-monitor.
# Drop on the PC at: Desktop\_Review\house_elf_desk.py
# Dry-run until Desktop\_Review\ELF_GO exists (empty file is enough).
# Continuous, separate from Grok usage: Task Scheduler every 15 min, two tasks, one lock.
#   schtasks /Create /TN HouseElf-I /SC MINUTE /MO 15 /TR "py -3 \"%USERPROFILE%\Desktop\_Review\house_elf_desk.py\" --seat elf1"
#   schtasks /Create /TN HouseElf-II /SC MINUTE /MO 15 /TR "py -3 \"%USERPROFILE%\Desktop\_Review\house_elf_desk.py\" --seat elf2"
# Undo: py -3 house_elf_desk.py --undo
# Never deletes. Niffler Hoard exempt. Does not touch foundation-next.html.

from __future__ import annotations

import argparse
import json
import os
import sys
import time
from pathlib import Path

EXEMPT_PARTS = (
    "niffler", "hoard", "foundation-next", "hall-next", "pulse-check",
    "locker-sync", "uspto", "patent center",
)
LOCK_STALE_S = 600
MAX_MOVES = 13
REVIEW = "_Review"

EXT_DEST = {
    ".py": "Projects", ".js": "Projects", ".html": "Projects", ".css": "Projects",
    ".md": "Projects", ".json": "Projects", ".txt": "Projects", ".ps1": "Projects",
    ".stl": "3D Assets", ".obj": "3D Assets", ".blend": "3D Assets", ".fbx": "3D Assets",
    ".glb": "3D Assets", ".gltf": "3D Assets", ".3mf": "3D Assets",
    ".url": "Links", ".webloc": "Links", ".lnk": "Links",
}


def desktop() -> Path:
    return Path(os.environ.get("USERPROFILE", str(Path.home()))) / "Desktop"


def review_dir(desk: Path) -> Path:
    p = desk / REVIEW
    p.mkdir(exist_ok=True)
    return p


def exempt(path: Path) -> bool:
    blob = str(path).lower()
    return any(part in blob for part in EXEMPT_PARTS)


def acquire_lock(rev: Path, seat: str) -> bool:
    lock = rev / "house_elf.lock"
    now = time.time()
    if lock.exists():
        try:
            age = now - lock.stat().st_mtime
        except OSError:
            age = 0
        if age < LOCK_STALE_S:
            return False
    lock.write_text(json.dumps({"seat": seat, "pid": os.getpid(), "t": now}), encoding="utf-8")
    return True


def release_lock(rev: Path) -> None:
    lock = rev / "house_elf.lock"
    try:
        lock.unlink()
    except OSError:
        pass


def log_line(rev: Path, row: dict) -> None:
    path = rev / "undo-log.jsonl"
    with path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(row, ensure_ascii=True) + "\n")


def dest_for(desk: Path, item: Path, seat: str) -> Path | None:
    if seat == "elf1":
        name = EXT_DEST.get(item.suffix.lower(), REVIEW)
        folder = desk / name
        if name != REVIEW and not folder.is_dir():
            folder = desk / REVIEW
        return folder / item.name
    # elf2: only files already in _Review root, older than 30 min, into typed subfolders
    if item.parent.name != REVIEW:
        return None
    if time.time() - item.stat().st_mtime < 1800:
        return None
    sub = EXT_DEST.get(item.suffix.lower(), "unsorted")
    folder = item.parent / sub
    folder.mkdir(exist_ok=True)
    return folder / item.name


def cycle(seat: str) -> dict:
    desk = desktop()
    rev = review_dir(desk)
    go = (rev / "ELF_GO").exists()
    if not acquire_lock(rev, seat):
        return {"seat": seat, "status": "lock-held", "moved": 0, "skipped": 0, "dry": not go}
    moved = skipped = 0
    try:
        if seat == "elf1":
            items = [p for p in desk.iterdir() if p.is_file()]
        else:
            items = [p for p in rev.iterdir() if p.is_file() and p.name not in {"undo-log.jsonl", "house_elf.lock", "ELF_GO", "house_elf_desk.py"}]
        for item in items:
            if moved >= MAX_MOVES:
                skipped += 1
                continue
            if exempt(item) or item.name.startswith("house_elf") or item.name in {"ELF_GO", "undo-log.jsonl"}:
                skipped += 1
                continue
            target = dest_for(desk, item, seat)
            if target is None or target == item:
                skipped += 1
                continue
            if target.exists():
                skipped += 1
                continue
            row = {"t": time.strftime("%Y-%m-%dT%H:%M:%S"), "seat": seat, "src": str(item), "dst": str(target), "dry": not go}
            if go:
                item.rename(target)
                moved += 1
            else:
                skipped += 1
            log_line(rev, row)
    finally:
        release_lock(rev)
    return {"seat": seat, "status": "closed", "moved": moved, "skipped": skipped, "dry": not go, "undo": str(rev / "undo-log.jsonl")}


def undo(rev: Path) -> int:
    path = rev / "undo-log.jsonl"
    if not path.exists():
        return 0
    n = 0
    rows = [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
    for row in reversed(rows):
        if row.get("dry"):
            continue
        src, dst = Path(row["dst"]), Path(row["src"])
        if src.exists() and not dst.exists():
            dst.parent.mkdir(exist_ok=True)
            src.rename(dst)
            n += 1
    return n


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--seat", choices=("elf1", "elf2"), default="elf1")
    ap.add_argument("--undo", action="store_true")
    args = ap.parse_args()
    desk = desktop()
    rev = review_dir(desk)
    if args.undo:
        print(json.dumps({"undone": undo(rev)}))
        return 0
    print(json.dumps(cycle(args.seat)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

