from __future__ import annotations

import json
import os
import time
from pathlib import Path

import numpy as np

CAP = 13
PAUSE_S = 60
REVIEW = "_Review"
SKIP_SUFFIXES = {".lnk", ".bat", ".cmd", ".exe", ".msi"}
SKIP_NAMES = {
    "desktop.ini", "thumbs.db", "house_elf.lock", "undo-log.jsonl",
    "house_elf_report.json", "sharpen.json", "learned_skips.json",
    "balance.json", "progress.json", "STOP", "ELF_HOLD", "ELF_GO",
    "house_elf_protocol.py", "house_elf_pair.py", "house_elf_balance.py",
    "house_elf_numpy_hybrid.py", "HOUSE_ELF_PAIR.txt",
}
EXEMPT = ("niffler", "hoard", "foundation-next", "hall-next", "pulse-check", "uspto")
EXT_DEST = {
    ".py": "Projects", ".js": "Projects", ".html": "Projects", ".md": "Projects",
    ".txt": "Projects", ".ps1": "Projects", ".json": "Projects",
    ".stl": "3D Assets", ".obj": "3D Assets", ".blend": "3D Assets",
    ".url": "Links",
}

def desktop() -> Path:
    home = Path(os.environ.get("USERPROFILE", str(Path.home())))
    one = home / "OneDrive" / "Desktop"
    return one if one.is_dir() else home / "Desktop"

def review_dir(desk: Path) -> Path:
    p = desk / REVIEW
    p.mkdir(exist_ok=True)
    return p

def exempt(path: Path, extra: set[str]) -> bool:
    blob = str(path).lower()
    if path.name.lower() in SKIP_NAMES or path.name.lower() in extra or path.suffix.lower() in SKIP_SUFFIXES:
        return True
    return any(part in blob for part in EXEMPT)

def learned(rev: Path) -> set[str]:
    try:
        data = json.loads((rev / "learned_skips.json").read_text(encoding="utf-8"))
        return {str(n).lower() for n in data.get("names", [])}
    except (OSError, json.JSONDecodeError):
        return set()

def save_skip(rev: Path, name: str) -> None:
    path = rev / "learned_skips.json"
    try:
        names = json.loads(path.read_text(encoding="utf-8")).get("names", [])
    except (OSError, json.JSONDecodeError):
        names = []
    if name.lower() not in {str(n).lower() for n in names}:
        names.append(name)
    path.write_text(json.dumps({"names": names[-20:]}), encoding="utf-8")

def dest_for(desk: Path, item: Path, seat: str) -> Path | None:
    if seat == "elf1":
        folder_name = EXT_DEST.get(item.suffix.lower(), REVIEW)
        folder = desk / folder_name
        if folder_name != REVIEW and not folder.is_dir():
            folder = desk / REVIEW
        return folder / item.name
    if item.parent.name != REVIEW or time.time() - item.stat().st_mtime < 1800:
        return None
    sub = EXT_DEST.get(item.suffix.lower(), "unsorted")
    folder = item.parent / sub
    folder.mkdir(exist_ok=True)
    return folder / item.name

def act(seat: str, desk: Path, rev: Path, extra: set[str]) -> dict:
    if seat == "balance":
        return {"seat": seat, "moved": 0, "skipped": 0, "names": []}
    root = desk if seat == "elf1" else rev
    moved = 0
    skipped = 0
    names = []
    hold = (rev / "ELF_HOLD").exists()
    for item in [p for p in root.iterdir() if p.is_file()]:
        if moved >= CAP or exempt(item, extra):
            skipped += 1
            continue
        target = dest_for(desk, item, seat)
        if target is None or target == item or target.exists():
            skipped += 1
            continue
        if not hold:
            item.rename(target)
            moved += 1
            names.append(item.name)
            with (rev / "undo-log.jsonl").open("a", encoding="utf-8") as handle:
                handle.write(json.dumps({"t": time.strftime("%Y-%m-%dT%H:%M:%S"), "seat": seat, "src": str(item), "dst": str(target)}) + "\n")
        else:
            skipped += 1
    return {"seat": seat, "moved": moved, "skipped": skipped, "names": names}

def balance(e1: dict, e2: dict, rev: Path) -> dict:
    bad = []
    for row in (e1, e2):
        for name in row.get("names", []):
            if name.lower() in {n.lower() for n in SKIP_NAMES}:
                bad.append(name)
                save_skip(rev, name)
    table = np.array([
        [e1.get("moved", 0), e1.get("skipped", 0), len(e1.get("names", []))],
        [e2.get("moved", 0), e2.get("skipped", 0), len(e2.get("names", []))],
        [0, 0, len(bad)],
    ], dtype=int)
    state = "HOLD" if not bad and int(table[:, 0].sum()) == 0 else "STEP"
    line = {"seat": "balance", "state": state, "bad": bad, "table": table.tolist(), "t": time.strftime("%Y-%m-%dT%H:%M:%S")}
    (rev / "balance.json").write_text(json.dumps(line, indent=2), encoding="utf-8")
    progress = rev / "progress.json"
    try:
        prev = json.loads(progress.read_text(encoding="utf-8"))
        step = int(prev.get("step", 0))
    except (OSError, json.JSONDecodeError, ValueError):
        step = 0
    if state == "STEP":
        step += 1
    progress.write_text(json.dumps({"step": step, "state": state, "t": line["t"]}, indent=2), encoding="utf-8")
    return line

def activate() -> None:
    desk = desktop()
    rev = review_dir(desk)
    print(json.dumps({"activated": True, "desk": str(desk)}), flush=True)
    while True:
        if (rev / "STOP").exists():
            print(json.dumps({"state": "stopped"}), flush=True)
            return
        extra = learned(rev)
        e1 = act("elf1", desk, rev, extra)
        e2 = act("elf2", desk, rev, extra)
        bal = balance(e1, e2, rev)
        plate = {"elf1": e1, "elf2": e2, "balance": bal}
        (rev / "house_elf_report.json").write_text(json.dumps(plate, indent=2), encoding="utf-8")
        print(json.dumps(plate), flush=True)
        time.sleep(PAUSE_S)

if __name__ == "__main__":
    activate()

