# arbiter_rule.py
# Built from the closed tether rule, not from a core label.
# delta = interior - claimed.
# missing number -> HOLD. delta >= 0 -> GRANT. delta < 0 -> REFUSE.
# A second shot on a closed axis is refused. Moves nothing.

from __future__ import annotations

import json
import os
import time
from pathlib import Path

def desk() -> Path:
    home = Path(os.environ.get("USERPROFILE", str(Path.home())))
    one = home / "OneDrive" / "Desktop"
    return one if one.is_dir() else home / "Desktop"

def read(path: Path) -> dict:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}

def shot(axis: str, interior, claimed, closed: dict) -> dict:
    if axis in closed:
        return {"axis": axis, "verdict": "REFUSE", "why": "already closed"}
    if interior is None or claimed is None:
        return {"axis": axis, "verdict": "HOLD", "delta": None}
    delta = int(interior) - int(claimed)
    verdict = "GRANT" if delta >= 0 else "REFUSE"
    closed[axis] = verdict
    return {"axis": axis, "verdict": verdict, "delta": delta}

def main() -> int:
    root = desk()
    rev = root / "_Review"
    rev.mkdir(exist_ok=True)
    house = read(rev / "progress.json")
    hub = read(root / "Hub" / "refine.json")
    closed_path = rev / "arbiter_closed.json"
    closed = read(closed_path)
    house_shot = shot(
        "house",
        house.get("learned") if isinstance(house.get("learned"), int) else (len(house.get("learned")) if isinstance(house.get("learned"), list) else None),
        house.get("bad", house.get("unmatched")),
        closed,
    )
    marks = hub.get("marks")
    glass_shot = shot(
        "aesthetic",
        len(marks) if isinstance(marks, list) else hub.get("mark_count"),
        3 if hub else None,
        closed,
    )
    if house_shot["verdict"] == "HOLD" or glass_shot["verdict"] == "HOLD":
        verdict = "HOLD"
    elif house_shot["verdict"] == "REFUSE" or glass_shot["verdict"] == "REFUSE":
        verdict = "REFUSE"
    else:
        verdict = "GRANT"
    plate = {
        "t": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "rule": "delta = interior - claimed",
        "observer": verdict,
        "house": house_shot,
        "aesthetic": glass_shot,
        "moved": 0,
    }
    closed_path.write_text(json.dumps(closed, indent=2), encoding="utf-8")
    (rev / "arbiter.json").write_text(json.dumps(plate, indent=2), encoding="utf-8")
    print(json.dumps(plate, indent=2))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

# arbiter_full.py
# Closed numbers only. 3-4-5, cos 0.6, sin 0.8, 2.56.
# Slots 0 observe, 1 echo, 2 shadow, 3 seal. Origin (0, 0).
# interior - claimed. Missing HOLD. Negative REFUSE. Else GRANT.
# Mask 0x800 is a pin field, not the score. Moves nothing.

from __future__ import annotations

import json
import os
import time
from pathlib import Path

COS = 0.6
SIN = 0.8
TWO_SIN_SQ = 2.56
MASK = 0x800

def desktop() -> Path:
    home = Path(os.environ.get("USERPROFILE", str(Path.home())))
    one = home / "OneDrive" / "Desktop"
    return one if one.is_dir() else home / "Desktop"

def load(path: Path) -> dict:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except (OSError, json.JSONDecodeError):
        return {}

def verdict(interior, claimed, seen, name):
    if name in seen:
        return {"verdict": "REFUSE", "delta": None}
    if interior is None or claimed is None:
        return {"verdict": "HOLD", "delta": None}
    delta = interior - claimed
    if delta < 0:
        return {"verdict": "REFUSE", "delta": delta}
    seen.add(name)
    return {"verdict": "GRANT", "delta": delta}

def main() -> int:
    desk = desktop()
    rev = desk / "_Review"
    hub = desk / "Hub"
    rev.mkdir(exist_ok=True)
    progress = load(rev / "progress.json")
    refine = load(hub / "refine.json")
    learned = progress.get("learned")
    seen = set()
    hearth = verdict(len(learned) if isinstance(learned, list) else None, 0 if progress else None, seen, "house")
    glass = verdict(1 if (hub / "Hub.html").exists() else None, 1 if refine else None, seen, "hub")
    plate = {
        "t": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "origin": [0, 0],
        "constants": {"cos": COS, "sin": SIN, "two_sin_sq": TWO_SIN_SQ},
        "observer": {"slot": 0, "pin_mask": MASK, "used_as_score": False, "moved": 0},
        "hearth": {"slot": 1, **hearth, "moved": 0},
        "glass": {"slot": 2, **glass, "moved": 0},
        "seal": "GRANT" if hearth["verdict"] == "GRANT" and glass["verdict"] == "GRANT" else "HOLD",
    }
    (rev / "arbiter_full.json").write_text(json.dumps(plate, indent=2), encoding="utf-8")
    print(json.dumps(plate, indent=2))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
